/* Serializable rules: no renderer, clock or DOM dependency. */
(function(root){
 const create=()=>({schema:1,wave:0,completed:0,stage:'preparation',enemies:[],elapsed:0,attackCooldown:0,hurtCooldown:0,lightCooldown:0,shield:0,targetId:null,settledWave:0,dialogueIndex:0,checkpoint:null});
 function ensure(game){root.ResidentCombat?.ensure(game);root.VillageProgress?.ensure(game);game.defense??=create();for(const [key,value]of Object.entries(create()))if(game.defense[key]===undefined)game.defense[key]=value;game.defense.enemies=Array.isArray(game.defense.enemies)?game.defense.enemies:[];game.story.waveTopics??=[];game.story.residentRequests??=[];game.domovoy.upgrades??={};if(root.ResidentCombat&&game.defense.stage==='active'&&!game.defense.residentBattle){const checkpoint=game.defense.checkpoint;if(checkpoint){checkpoint.residents??=JSON.parse(JSON.stringify(game.villagers));checkpoint.residentLosses??=JSON.parse(JSON.stringify(game.story.residentLosses||[]));checkpoint.residentJournal??=JSON.parse(JSON.stringify(game.journal||[]));}root.ResidentCombat.begin(game);}return game.defense}
 function count(wave,difficulty){return 4+(wave-1)*3+(difficulty==='Былина'?2:difficulty==='Лучина'?-1:0)}
 const alive=d=>d.enemies.filter(e=>e.hp>0&&(e.kind!=='leshy'||e.mode==='duel'));
 function begin(game,enemies){const d=ensure(game);if(game.phase!=='day'||d.completed>=3||!enemies.length)return false;const ready=root.VillageProgress?.readiness(game);if(ready&&!ready.ready)return false;const fuel=ready?.fuel||0;const charcoal=game.resources.charcoal||0;game.resources.charcoal=charcoal-fuel;d.fueledTotems=fuel;const wave=d.completed+1;d.battleStory=null;d.guardCooldowns={};Object.assign(d,{wave,stage:'active',enemies,elapsed:0,attackCooldown:0,hurtCooldown:0,lightCooldown:0,lightUntil:0,targetId:null,shield:Math.min(3,(game.hero.learnedSkills.includes('wall')?1:0)+(game.domovoy.upgrades.ward?1:0)+(game.buildings.tower>0?1:0)),checkpoint:{hp:game.hero.hp,bag:JSON.parse(JSON.stringify(game.hero.bag)),position:{...(game.hero.scenePosition||{x:1.8,z:-2})},candles:game.resources.candles,charcoal,residents:root.ResidentCombat?JSON.parse(JSON.stringify(game.villagers)):null,residentLosses:JSON.parse(JSON.stringify(game.story.residentLosses||[])),residentJournal:JSON.parse(JSON.stringify(game.journal||[]))}});root.ResidentCombat?.begin(game);game.phase='combat';game.ui.sceneTime='night';return true}
 function hit(game,id){const d=ensure(game);if(d.stage!=='active'||d.attackCooldown>0)return false;const e=d.enemies.find(e=>e.id===id&&e.hp>0);if(!e)return false;if(e.kind==='leshy'&&(e.mode!=='duel'||root.BattleNarrative?.canHit(game,e)===false))return false;const damage=e.kind==='leshy'?1:Math.max(1,1+Math.floor(Math.max(0,game.hero.stats.str-3)/3)+(game.hero.learnedSkills.includes('strike')?1:0));e.hp=Math.max(0,e.hp-damage);d.attackCooldown=.85;return true}
 function hurt(game){const d=ensure(game);if(d.stage!=='active'||d.hurtCooldown>0)return false;d.hurtCooldown=2.8;if(d.shield>0){d.shield--;return 'blocked'}game.hero.hp=Math.max(0,game.hero.hp-1);if(!game.hero.hp){d.stage='defeat';game.phase='defeat'}return true}
 function win(game){const d=ensure(game);if(d.stage!=='active'||alive(d).length)return false;const boss=d.enemies.find(e=>e.kind==='leshy');if(d.wave===3&&boss?.hp>0&&boss.mode!=='duel'){boss.mode='duel';d.targetId=null;return false}root.ResidentCombat?.finishQuota(game);d.stage='dialogue';game.phase='waveDialogue';d.dialogueIndex=0;d.targetId=null;return true}
 function unlock(game){const d=ensure(game);for(const source of ['oak','resident']){const list=source==='oak'?game.story.waveTopics:game.story.residentRequests,id=source+'-wave-'+d.wave;if(!list.some(t=>t.id===id))list.push({id,wave:d.wave,status:'waiting-script',read:false,speaker:source==='resident'?game.villagers.filter(v=>v.alive!==false&&v.storyActive!==false)[(d.wave-1)%Math.max(1,game.villagers.filter(v=>v.alive!==false&&v.storyActive!==false).length)]?.id:null})}}
 function settle(game){const d=ensure(game);if(d.stage!=='dialogue'||d.settledWave>=d.wave)return false;d.settledWave=d.wave;d.completed=d.wave;game.ui.nightCount++;unlock(game);d.stage='outcome';game.phase='outcome';return true}
 function retry(game){const d=ensure(game);if(d.stage!=='defeat'||!d.checkpoint)return false;game.hero.hp=d.checkpoint.hp;game.hero.bag=JSON.parse(JSON.stringify(d.checkpoint.bag));game.hero.scenePosition={...d.checkpoint.position};game.resources.candles=d.checkpoint.candles??game.resources.candles;d.enemies.forEach(e=>{e.hp=e.maxHp;e.x=e.spawnX;e.z=e.spawnZ;e.stunnedUntil=0;e.repelUntil=0;e.repelReadyAt=0;if(e.kind==='leshy'){e.mode='command';e.hitAttempts=0;e.dodgeReadyAt=0}});d.battleStory=null;d.guardCooldowns={};Object.assign(d,{stage:'active',elapsed:0,attackCooldown:0,hurtCooldown:0,lightCooldown:0,lightUntil:0,targetId:null,shield:Math.min(3,(game.hero.learnedSkills.includes('wall')?1:0)+(game.domovoy.upgrades.ward?1:0)+(game.buildings.tower>0?1:0))});game.phase='combat';root.ResidentCombat?.restore(game,d.checkpoint);return true}
 const SHOP=[{id:'herb',name:'Зелье плакун-травы',description:'Восстанавливает 2 сердца. Лечение не расходуется при полных жизнях.',cost:{silver:12},item:{itemId:'Корень плакун-травы',qty:1,use:'heal'},icon:56},{id:'grain',name:'Зерно · 5',description:'Общий запас еды для деревни.',cost:{silver:10},gain:{grain:5},icon:64},{id:'salt',name:'Соль · 2',description:'Для оберегов и обмена.',cost:{silver:18},gain:{salt:2},icon:67},{id:'candles',name:'Свечи · 3',description:'Для ручного фонаря и разведки. Тотемы питаются углём.',cost:{silver:9},gain:{candles:3},icon:56},{id:'ward',name:'Оберег бережника · +1 защита',description:'Поглощает один дополнительный удар каждую ночь. Постоянное улучшение; покупается один раз.',cost:{silver:35,salt:3,cloth:1},upgrade:'ward',icon:37}];
 const EXCHANGES=[{id:'wood-stone',name:'Брёвна на камень',cost:{wood:10},gain:{stone:5},icon:63},{id:'stone-wood',name:'Камень на брёвна',cost:{stone:8},gain:{wood:5},icon:62},{id:'wood-rope',name:'Верёвка · 3',description:'Для ремонта домов, палаток и вышек.',cost:{wood:6},gain:{rope:3},icon:54},{id:'stone-paint',name:'Красная краска · 3',description:'Для защитных знаков на тотемах.',cost:{stone:4},gain:{paint:3},icon:54},{id:'wood-charcoal',name:'Древесный уголь · 4',description:'Один уголь на каждый тотем перед ночью.',cost:{wood:4},gain:{charcoal:4},icon:56},{id:'grain-herb',name:'Зерно на лечебное зелье',cost:{grain:8},item:{itemId:'Корень плакун-травы',qty:1,use:'heal'},icon:56},{id:'wood-silver',name:'Продать брёвна',cost:{wood:10},gain:{silver:8},icon:43}];
 function trade(game,id,tab){if(game.phase!=='day')return {ok:false,reason:'Торговля доступна между нападениями.'};const row=(tab==='exchange'?EXCHANGES:SHOP).find(r=>r.id===id);if(!row)return {ok:false,reason:'Предложение не найдено.'};ensure(game);if(root.VillageProgress&&!root.VillageProgress.repairCount(game,'market_ruin')&&!root.VillageProgress.repairCount(game,'tent_ruin'))return {ok:false,reason:'Сначала восстанови торговое место Домового.'};if(row.upgrade&&game.domovoy.upgrades[row.upgrade])return {ok:false,reason:'Улучшение уже куплено.'};if(Object.entries(row.cost).some(([k,v])=>!Number.isFinite(game.resources[k])||game.resources[k]<v))return {ok:false,reason:'Не хватает ресурсов.'};for(const[k,v]of Object.entries(row.cost))game.resources[k]-=v;for(const[k,v]of Object.entries(row.gain||{}))game.resources[k]+=v;if(row.item){const item=game.hero.bag.find(i=>i.itemId===row.item.itemId);if(item)item.qty+=row.item.qty;else game.hero.bag.push({...row.item})}if(row.upgrade)game.domovoy.upgrades[row.upgrade]=true;if(root.VillageProgress){const p=root.VillageProgress.ensure(game);p.trades=(p.trades||0)+1}return {ok:true,row}}
 function flash(game){const d=ensure(game);if(d.stage!=='active'||d.lightCooldown>0||game.resources.candles<1||!game.hero.bag.some(i=>i.itemId==='Фонарь'&&i.qty>0))return false;const p=game.hero.scenePosition||{x:1.8,z:-2};const nearby=alive(d).filter(e=>Math.hypot(e.x-p.x,e.z-p.z)<=5);if(!nearby.length)return false;game.resources.candles--;d.lightCooldown=10;d.lightUntil=d.elapsed+3;nearby.forEach(e=>e.stunnedUntil=d.elapsed+3);return true}
 function heal(game){const item=game.hero.bag.find(i=>i.use==='heal'&&i.qty>0);if(!item||game.hero.hp>=game.hero.hpMax||game.hero.hp<=0)return false;item.qty--;game.hero.hp=Math.min(game.hero.hpMax,game.hero.hp+2);return true}
 const rules={create,ensure,count,alive,begin,hit,hurt,win,settle,retry,trade,heal,flash,SHOP,EXCHANGES};root.DefenseRules=rules;if(typeof module!=='undefined')module.exports=rules;
})(typeof window!=='undefined'?window:globalThis);
